38	/**
39	 * Transforms string attribute value into numeric value
40	 */
41	public class NumericAttributeTransformer implements DBDAttributeTransformer {
42	    private static final Log log = Log.getLog(NumericAttributeTransformer.class);
43	
44	    private static final String PROP_TYPE = "type";
45	    private static final String PROP_LENIENT = "lenient";
46	
47	    @Override
48	    public void transformAttribute(@NotNull DBCSession session, @NotNull DBDAttributeBinding attribute, @NotNull List<Object[]> rows, @NotNull Map<String, Object> options) throws DBException {
49	        final String type = CommonUtils.toString(options.get(PROP_TYPE), "double");
50	        final boolean lenient = CommonUtils.getBoolean(options.get(PROP_LENIENT), false);
51	
52	        attribute.setTransformHandler(new NumericValueHandler(attribute.getValueHandler(), type, lenient));
53	        attribute.setPresentationAttribute(new TransformerPresentationAttribute(attribute, "numeric", -1, DBPDataKind.NUMERIC));
54	    }
55	
56	    private static class NumericValueHandler extends ProxyValueHandler {
57	        private final String type;
58	        private final boolean lenient;
59	
60	        public NumericValueHandler(@NotNull DBDValueHandler target, @NotNull String type, boolean lenient) {
61	            super(target);
62	            this.type = type;
63	            this.lenient = lenient;
64	        }
65	
66	        @NotNull
67	        @Override
68	        public Class<?> getValueObjectType(@NotNull DBSTypedObject attribute) {
69	            return Object.class;
70	        }
71	
72	        @Override
73	        public void bindValueObject(@NotNull DBCSession session, @NotNull DBCStatement statement, @NotNull DBSTypedObject type, int index, @Nullable Object value) throws DBCException {
74	            super.bindValueObject(session, statement, type, index, CommonUtils.toString(value));
75	        }
76	
77	        @Nullable
78	        @Override
79	        public Object getValueFromObject(@NotNull DBCSession session, @NotNull DBSTypedObject type, @Nullable Object object, boolean copy, boolean validateValue) throws DBCException {
80	            if (object instanceof String) {
81	                object = parseValue((String) object, this.type, this.lenient);
82	            }
83	            if (object instanceof Number) {
84	                return object;
85	            }
86	            return super.getValueFromObject(session, type, object, copy, validateValue);
87	        }
88	
89	        @NotNull
90	        @Override
91	        public String getValueDisplayString(@NotNull DBSTypedObject column, @Nullable Object value, @NotNull DBDDisplayFormat format) {
92	            if (value instanceof String) {
93	                value = parseValue((String) value, this.type, this.lenient);
94	            }
95	            if (value instanceof Number) {
96	                return CommonUtils.toString(value);
97	            }
98	            if (value == null) {
99	                return "";
100	            }
101	            return super.getValueDisplayString(column, value, format);
102	        }
103	
104	        @Nullable
105	        private static Object parseValue(@NotNull String value, @NotNull String type, boolean lenient) {
106	            try {
107	                switch (type) {
108	                    case "byte":
109	                        return Byte.parseByte(value);
110	                    case "short":
111	                        return Short.parseShort(value);
112	                    case "int":
113	                        return Integer.parseInt(value);
114	                    case "long":
115	                        return Long.parseLong(value);
116	                    case "float":
117	                        return Float.parseFloat(value);
118	                    case "double":
119	                        return Double.parseDouble(value);
120	                    default:
121	                        return null;
122	                }
123	            } catch (NumberFormatException e) {
124	                if (lenient) {
125	                    log.trace("Error converting string '" + value + "' to " + type, e);
126	                }
127	                return value;
128	            }
129	        }
130	    }
131	}
