274	                        char c2 = queryString.charAt(k);
275	                        if (c2 == c && queryString.charAt(k - 1) != '\\') {
276	                            i = k;
277	                            c = c2;
278	                            break;
279	                        } else {
280	                            formatted.append(c2);
281	                        }
282	                    }
283	                    break;
284	                }
285	            }
286	            formatted.append(c);
287	        }
